package com.ruoyi.fashion.infrastructure.persistence.image;
import java.util.*;
import org.springframework.stereotype.Repository;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import com.ruoyi.fashion.configuration.FashionModuleEnabled;
import com.ruoyi.fashion.application.proposal.*;
import tools.jackson.databind.ObjectMapper;
@Repository @FashionModuleEnabled
public class JdbcProposalImageRepository implements ProposalImageRepository {
    private final NamedParameterJdbcTemplate jdbc; private final ObjectMapper mapper;
    public JdbcProposalImageRepository(@Qualifier("fashionJdbcTemplate") NamedParameterJdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
    private List<ProposalImageTask> query(String where,Map<String,?> args) {
        return jdbc.query("select * from fq_proposal_image_task where "+where,args,(rs,n)->new ProposalImageTask(rs.getString("id"),rs.getString("pool_id"),rs.getLong("owner_id"),rs.getLong("draft_version"),rs.getString("combo_id"),rs.getString("input_hash"),mapper.readTree(rs.getString("input_json")),rs.getString("request_key"),rs.getString("status"),rs.getString("provider_task_id"),mapper.readTree(rs.getString("result_json")==null?"[]":rs.getString("result_json")),rs.getString("error_message"),mapper.readTree(rs.getString("review_json")==null?"{}":rs.getString("review_json")),rs.getLong("row_version"),new ProposalImageTask.Costs(rs.getString("provider_code"),rs.getString("model"),rs.getBigDecimal("estimated_cost"),rs.getBigDecimal("actual_cost"),rs.getString("cost_currency"),rs.getString("billing_status"),time(rs,"submitted_at"),time(rs,"finished_at"),time(rs,"cancel_requested_at"),time(rs,"next_query_at"),rs.getInt("retry_count"))));
    }
    public Optional<ProposalImageTask> find(String id,long owner){return query("id=:id and owner_id=:owner",Map.of("id",id,"owner",owner)).stream().findFirst();}
    public Optional<ProposalImageTask> request(String key,long owner){return query("request_key=:key and owner_id=:owner",Map.of("key",key,"owner",owner)).stream().findFirst();}
    public List<ProposalImageTask> list(String poolId,long owner){return query("pool_id=:pool and owner_id=:owner order by create_time desc",Map.of("pool",poolId,"owner",owner));}
    private static java.time.Instant time(java.sql.ResultSet rs,String name)throws java.sql.SQLException{var value=rs.getTimestamp(name);return value==null?null:value.toInstant();}
    private Map<String,Object> params(ProposalImageTask t){var m=new HashMap<String,Object>();m.put("id",t.id());m.put("pool",t.poolId());m.put("owner",t.ownerId());m.put("draft",t.draftVersion());m.put("combo",t.combinationId());m.put("hash",t.inputHash());m.put("inputs",mapper.writeValueAsString(t.inputs()));m.put("key",t.requestKey());m.put("status",t.status());m.put("provider",t.providerTaskId());m.put("results",mapper.writeValueAsString(t.results()));m.put("error",t.errorMessage());m.put("review",mapper.writeValueAsString(t.review()));var c=t.costs();m.put("providerCode",c.providerCode());m.put("model",c.model());m.put("estimate",c.estimatedCost());m.put("actual",c.actualCost());m.put("currency",c.currency());m.put("billing",c.billingStatus());m.put("submitted",timestamp(c.submittedAt()));m.put("finished",timestamp(c.finishedAt()));m.put("cancelAt",timestamp(c.cancelRequestedAt()));m.put("nextQuery",timestamp(c.nextQueryAt()));m.put("retry",c.retryCount());return m;}
    private static java.sql.Timestamp timestamp(java.time.Instant value){return value==null?null:java.sql.Timestamp.from(value);}
    public void insert(ProposalImageTask t){jdbc.update("insert into fq_proposal_image_task(id,pool_id,owner_id,draft_version,combo_id,input_hash,input_json,request_key,status,provider_task_id,result_json,error_message,review_json,row_version,provider_code,model,estimated_cost,actual_cost,cost_currency,billing_status,submitted_at,finished_at,cancel_requested_at,next_query_at,retry_count,create_time,update_time) values(:id,:pool,:owner,:draft,:combo,:hash,:inputs,:key,:status,:provider,:results,:error,:review,1,:providerCode,:model,:estimate,:actual,:currency,:billing,:submitted,:finished,:cancelAt,:nextQuery,:retry,current_timestamp,current_timestamp)",params(t));}
    public boolean update(ProposalImageTask t,long expected){var m=params(t);m.put("version",expected);return jdbc.update("update fq_proposal_image_task set status=:status,provider_task_id=:provider,result_json=:results,error_message=:error,review_json=:review,row_version=row_version+1,provider_code=:providerCode,model=:model,estimated_cost=:estimate,actual_cost=:actual,cost_currency=:currency,billing_status=:billing,submitted_at=:submitted,finished_at=:finished,cancel_requested_at=:cancelAt,next_query_at=:nextQuery,retry_count=:retry,update_time=current_timestamp where id=:id and owner_id=:owner and row_version=:version",m)==1;}
    public java.math.BigDecimal monthlyUsage(String currency){java.math.BigDecimal value=jdbc.queryForObject("select coalesce(sum(case when billing_status='settled' then coalesce(actual_cost,0) else coalesce(estimated_cost,0) end),0) from fq_proposal_image_task where cost_currency=:currency and create_time>=date_format(current_timestamp,'%Y-%m-01')",Map.of("currency",currency),java.math.BigDecimal.class);return value==null?java.math.BigDecimal.ZERO:value;}
    public boolean hasUnpricedAcceptedTasks(){Long count=jdbc.queryForObject("select count(*) from fq_proposal_image_task where provider_task_id is not null and ((billing_status<>'settled' and (estimated_cost is null or cost_currency is null)) or (billing_status='settled' and actual_cost is null))",Map.of(),Long.class);return count!=null&&count>0;}
    public List<ProposalImageTask> pending(int limit){return query("status in ('submitting','queued','running','cancel_requested','unknown') and retry_count<8 and (provider_task_id is not null or status='submitting') and (next_query_at is null or next_query_at<=current_timestamp) order by update_time limit "+Math.max(1,Math.min(limit,50)),Map.of());}
}
